t."}, {"id": "4a2077f1-727f-41b5-87af-7c91886ff330", "type": "subtopic", "title": "Source diversity and independence", "children": [{"id": "9c6bac11-af89-45e3-aa25-016bdc75ab2b", "type": "concept", "title": "source audits"}, {"id": "afd57d69-4fd4-4f1a-b40d-b4d8e561658b", "type": "concept", "title": "rotating source lists"}, {"id": "d16d9b99-0d85-4869-84cc-685fc44995d4", "type": "concept", "title": "independence checks"}], "description": "The course stresses avoiding overreliance on powerful insiders or familiar voices."}, {"id": "3fac60ca-947b-45a6-b996-03d3dbb5c772", "type": "subtopic", "title": "Confidential and vulnerable sources", "children": [{"id": "f271264b-95ad-43cb-9c4e-4000d57e7132", "type": "concept", "title": "ground rules"}, {"id": "f85e7615-70db-4800-9305-3510b88f6474", "type": "concept", "title": "risk assessment"}, {"id": "e4e12eaa-231e-476d-9902-44682d871d35", "type": "concept", "title": "source protection"}], "description": "Students learn when confidentiality is justified and how to protect sources ethically."}]}, {"id": "685a55cd-fe14-43cb-8992-f2cc7de1155f", "type": "topic", "title": "Sports Reporting Fundamentals", "description": "Students approach sports as competition, business, culture, labor, education, health, identity, and public money, not only as game results.", "children": [{"id": "2fe241e4-4afb-49d9-a81b-8fcf823f5329", "type": "subtopic", "title": "Game and event coverage", "children": [{"id": "a597b44c-b4f8-46a5-94d5-702a16223afe", "type": "concept", "title": "gamer structure"}, {"id": "16600ff6-a941-4576-be31-0d1926529406", "type": "concept", "title": "quotes and color"}, {"id": "824f4ec9-4f37-43c7-b2ca-2f170b68d1e8", "type": "concept", "title": "deadline updates"}], "description": "Students practice fast, accurate coverage of games, matches, press conferences, and breaking sports news."}, {"id": "26b50578-4090-4a8c-9290-3e30f259375e", "type": "subtopic", "title": "Athletes, labor, and institutions", "children": [{"id": "5bc67e9f-6a