"}, {"id": "2dd50038-29a7-4a34-9773-d98238da46c3", "type": "concept", "title": "editor handoffs"}], "description": "Students learn planning, verification, updates, and handoffs for live events."}, {"id": "a6fde5cd-30b0-40d6-a647-37a22229a2e3", "type": "subtopic", "title": "Breaking news on a beat", "children": [{"id": "09eb8a94-e498-4ee2-b23a-76aeae27c89b", "type": "concept", "title": "confirmation standards"}, {"id": "3becc755-de34-459d-a20c-a0b89226c0a1", "type": "concept", "title": "attribution"}, {"id": "60fc84e7-2954-420a-a0c2-51395a1d38dc", "type": "concept", "title": "updates"}], "description": "The class covers fast confirmation, cautious language, and avoiding rumor amplification."}, {"id": "59d08f79-f063-43e4-8057-c2b6c7663aeb", "type": "subtopic", "title": "Service journalism", "children": [{"id": "f6254746-bb37-4eb8-bd71-6f3d395db375", "type": "concept", "title": "how-to coverage"}, {"id": "c3cf9d18-e282-40e8-a3d5-e8a51946174a", "type": "concept", "title": "voter guides"}, {"id": "bc962f81-310a-42d0-b0d9-3da723fbbe55", "type": "concept", "title": "consumer guides"}], "description": "Students create useful coverage that helps people navigate decisions, deadlines, and systems."}, {"id": "0fdccb77-5918-4f2c-82bb-2563d8d4f52f", "type": "subtopic", "title": "Post-event follow-up", "children": [{"id": "4a147dff-213b-4781-9b1b-752b604de2d2", "type": "concept", "title": "accountability follow-ups"}, {"id": "bc78d136-5a27-4868-a177-661b35431a59", "type": "concept", "title": "impact checks"}, {"id": "7a43fb76-6173-4c2c-98a7-dbd3cc125e32", "type": "concept", "title": "second-day stories"}], "description": "Students learn that the real story often emerges after the event ends."}]}, {"id": "3edf79cb-900f-4cfe-9a24-cd3cfb3508f3", "type": "topic", "title": "Ethics in Beat Reporting", "description": "Students learn to manage proximity, access, expertise, conflicts, source pressure, and harm on beats where relationships are constant.", "children": [{"id": "4c48d48d-6a89-