  data = $sprejson${"slug": "specialized-reporting-sports-politics-business", "title": "Specialized Reporting (sports, politics, business)", "description": "An advanced beat-reporting course on building expertise, sources, evidence, and publishable stories in sports, politics, business, and adjacent specialized beats.", "topics": [{"id": "2c7f8e53-c0ba-4744-b625-779eea656956", "type": "topic", "title": "Choosing and Developing a Beat", "description": "Students learn to define a beat as a living system of institutions, people, records, routines, conflicts, and unanswered questions.", "children": [{"id": "afdf605f-5c1a-4771-9281-c18a546943e7", "type": "subtopic", "title": "Beat map and scope", "children": [{"id": "b1750006-b76d-43c4-acc9-4ce4451ef291", "type": "concept", "title": "institutions"}, {"id": "1204da56-e598-45cc-9f89-8d34a9eb6215", "type": "concept", "title": "stakeholders"}, {"id": "a4a1a874-d3c3-4562-94d8-7155c3123f09", "type": "concept", "title": "recurring calendars"}], "description": "Students identify the institutions, communities, events, records, and recurring decisions that make the beat reportable."}, {"id": "d8d6d995-ad6e-41af-98ea-39e47f982804", "type": "subtopic", "title": "Audience and public-interest needs", "children": [{"id": "3f4e9a9a-7e98-4903-b5d3-31a434bc2bac", "type": "concept", "title": "service journalism"}, {"id": "741d6fd8-1a7d-45bb-94dd-77d2b966e3aa", "type": "concept", "title": "accountability"}, {"id": "0dcb95f8-c181-4755-bcb2-8993bc9e1187", "type": "concept", "title": "affected communities"}], "description": "Students learn to ask what readers need to know to act, decide, participate, or hold power accountable."}, {"id": "0c2e2f21-89d5-4e2b-8439-ffeb8e6e2a23", "type": "subtopic", "title": "Beat rhythm", "children": [{"id": "a3d7a593-1908-4b7c-91f5-7afb2f899915", "type": "concept", "title": "daily coverage"}, {"id": "25f818d5-1c7e-4089-9c74-14ac10ed7fbe", "type": "concept", "title": "enterprise arcs"}, {"id": "d93871af-d74f-4be4